<script setup>
import { ref,onMounted,onBeforeUnmount,computed } from 'vue'
import { api } from '../api'
import { accountEpoch } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
import PageHeader from './ui/PageHeader.vue'
const data=ref(null),trial=ref(null),phase=ref(null),plans=ref([]),error=ref(''),mode=ref('gentle'),ack=ref(false),seconds=ref(''),explanation=ref(''),now=ref(Date.now()),writes=useWorkflowWrite('timers'),epoch=accountEpoch
let alive=true,clock=null,offset=0
const elapsed=computed(()=>{const row=data.value?.active;if(!row)return 0;return row.intervals.reduce((sum,i)=>sum+Math.max(0,((i.end?Date.parse(i.end):now.value+offset)-Date.parse(i.start))/1000),0)})
async function load(){try{const [result,daily,schedules,stage]=await Promise.all([api.flow('/timers'),api.flow('/trial'),api.flow('/plan-schedules'),api.flow('/phase')]);if(!alive||epoch!==accountEpoch)return;if(data.value?.active?.id!==result.active?.id){seconds.value='';explanation.value=result.active?.explanation||''}data.value=result;trial.value=daily;plans.value=schedules;phase.value=stage.phase;offset=Date.parse(result.server_now)-Date.now()}catch(e){error.value=e.message}}
async function act(path,body={}){try{await writes.send(path,body);await load();error.value=''}catch(e){error.value=e.message}}
async function start(kind,source_id,plan=null){await act('/timers',{kind,source_id,mode:mode.value,acknowledge_penalty:ack.value,...(plan?{source_version:plan.version,planned_minutes:plan.timing?.planned_minutes??plan.rule.planned_minutes??30}:{})})}
async function update(action,row=data.value?.active){if(!row)return;await act('/timers/'+row.id+'/'+action,{expected_version:row.version,...(['end-preview','explain'].includes(action)?{explanation:explanation.value,...(seconds.value!==''&&action==='end-preview'?{actual_seconds:Number(seconds.value)}:{})}:{})})}
function visibility(){if(!document.hidden)load()}
onMounted(()=>{load();clock=setInterval(()=>now.value=Date.now(),1000);document.addEventListener('visibilitychange',visibility)})
onBeforeUnmount(()=>{alive=false;clearInterval(clock);document.removeEventListener('visibilitychange',visibility)})
</script>
<template><div class="reading-page"><PageHeader title="计划与娱乐计时" description="按时间差显示用量；离线不自动认定违规，回来可以核对。"/><p v-if="error" class="error" role="alert">{{ error }}</p><button v-if="writes.pending.value" class="btn" @click="act(writes.pending.value.path,writes.pending.value.body)">恢复上次请求</button><section v-if="data?.active" class="card"><h2>{{ {plan:'计划',base:'基础娱乐',voucher:'金币券娱乐'}[data.active.kind] }} · {{ {running:'计时中',paused:'已暂停',review:'待确认结束'}[data.active.state] }}</h2><p v-if="data.active.contract?.plan_snapshot">{{ data.active.contract.plan_snapshot.name }} · 开始时预计 {{ data.active.contract.plan_snapshot.planned_minutes }} 分钟</p><p>本次已用 {{ Math.floor(elapsed/60) }} 分 {{ Math.floor(elapsed%60) }} 秒 · 本次可用 {{ data.active.limit_seconds/60 }} 分钟</p><p v-if="elapsed>=data.active.limit_seconds" role="status">约定时长已到，可以结束并核对。娱乐宽限3分钟；实际停止时间由你确认，不凭离线自动罚款。</p><p>来源 {{ data.active.kind==='voucher'?'本张券':'当前安排' }} #{{ data.active.source_id }} · 上次同步 {{ data.active.last_sync_at }}</p><button v-if="data.active.state==='running'" class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="update('pause')">暂停</button><button v-if="data.active.state==='paused'" class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="update('resume')">继续</button><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="update('sync')">确认仍在使用并同步</button><label>说明情况（先保存，可选分析）<textarea v-model="explanation" maxlength="4000"/></label><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!explanation.trim()" @click="update('explain')">保存说明</button><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!data.active.explanation" @click="update('analyze-explanation')">仅分析本次说明</button><p v-if="data.active.analysis">{{ data.active.analysis.summary }} · 建议实际 {{ data.active.analysis.suggested_seconds }} 秒（仍须你核对）</p><label>核对实际使用秒数（可空）<input type="number" min="0" v-model="seconds"/></label><button class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="update('end-preview')">结束并查看核对预览</button><div v-if="data.active.preview"><p v-if="data.active.preview.offline_interval">存在未同步区间，请核对实际停止时间；不会仅据离线自动罚款。</p><p>实际 {{ data.active.preview.actual_seconds }} 秒 · 处罚 {{ data.active.preview.penalty_charged }} 币 · 守时 {{ data.active.preview.ontime_awarded }} 币 · 金币变动 {{ data.active.preview.coin_delta }}</p><button class="btn primary" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="update('confirm')">确认实际用量与结算</button></div></section><section v-else class="card"><h2>开始一次计时</h2><label>娱乐约定<select v-model="mode"><option value="gentle">温和提醒，不扣币</option><option v-if="phase?.payload.accepted_mode==='strong'" value="strong">已接受加强：每5分钟4币，单次20／每日30</option><option value="strict">严格：宽限后每5分钟2币，单次10／每日20上限</option></select></label><label v-if="mode!=='gentle'"><input type="checkbox" v-model="ack"/>我在开始前同意本次处罚规则</label><button v-if="trial?.daily&&trial.daily.base_seconds>trial.daily.used_seconds" class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="start('base',trial.daily.id)">使用当天基础娱乐</button><article v-for="row in data?.vouchers" :key="row.redemption.id"><p>金币券 #{{ row.redemption.id }} · 剩余 {{ ((row.allowance?.total_seconds??row.redemption.duration_seconds)-(row.allowance?.used_seconds||0))/60 }} 分钟</p><button class="btn" :disabled="writes.busy.value||row.redemption.status==='fulfilled'" @click="start('voucher',row.redemption.id)">使用这张券（本次重新计时）</button></article><details><summary>开始计划计时</summary><button v-for="plan in plans.filter(p=>p.timing!==null&&(p.timing?.enabled??p.enabled))" :key="plan.id" class="btn" :disabled="writes.busy.value||!!writes.pending.value||!!writes.pending.value" @click="start('plan',plan.id,plan)">{{ plan.timing?.name||plan.name }} · {{ plan.timing?.planned_minutes??plan.rule.planned_minutes??30 }} 分钟</button></details></section><details><summary>历史计时与更正</summary><article v-for="row in data?.items.filter(r=>r.state==='ended')" :key="row.id"><p>{{ row.local_date }} · {{ row.kind }} · {{ row.settlement.actual_seconds }} 秒</p><label>说明<textarea v-model="explanation"/></label><label>更正实际秒数<input type="number" min="0" v-model="seconds"/></label><button class="btn" @click="update('end-preview',row)">预览更正</button><p v-if="row.preview">金币差额 {{ row.preview.coin_delta }}；历史流水保留。<button class="btn" @click="update('confirm',row)">确认更正</button></p></article></details></div></template>
